package com.careerpilot.modules.assessment.generation;
import com.careerpilot.config.AssessmentProperties;import org.slf4j.*;import org.springframework.stereotype.Service;import java.util.*;
@Service
public class AssessmentGenerationService{private static final Logger log=LoggerFactory.getLogger(AssessmentGenerationService.class);private final AssessmentProperties properties;private final AssessmentAiQuestionProvider provider;private final GeneratedQuestionValidator validator;public AssessmentGenerationService(AssessmentProperties properties,AssessmentAiQuestionProvider provider,GeneratedQuestionValidator validator){this.properties=properties;this.provider=provider;this.validator=validator;}public List<GeneratedQuestion>generateDrafts(AssessmentGenerationRequest request){if(!properties.aiGenerationEnabled())return List.of();if(request==null||request.targetRole()==null||request.targetRole().isBlank()||request.difficulty()==null||request.questionCount()<1||request.questionCount()>properties.maxQuestions()||request.skills()==null||request.skills().isEmpty())throw new IllegalArgumentException("Invalid generation request");try{List<GeneratedQuestion>drafts=provider.generate(request);return validator.validate(drafts,new HashSet<>(request.skills()),request.questionCount());}catch(RuntimeException exception){log.warn("Assessment AI generation unavailable model={} reason={}",provider.model(),exception.getClass().getSimpleName());return List.of();}}}
